# Lab 07 - radio between two boards. Flash the SAME main.py on both.
# A sends "btn:<seq>:A", B sends "tmp:<seq>:<temperature>"; the other board
# decodes, drops duplicates and garbage, and prints what it received.
from microbit import *
import radio

GROUP = 7                  # group: both boards must use the same number (0-255)
KINDS = ("btn", "tmp")     # message format "<kind>:<seq>:<value>", text only
radio.config(group=GROUP)  # radio is already on after `import radio` (V2)


def encode(kind, seq, value):
    # one line of text; ":" separates fields, so values must not contain ":"
    return "{}:{}:{}".format(kind, seq, value)


def decode(text):
    # validate everything that came over the air: format, kind, sequence number
    parts = text.split(":")
    if len(parts) != 3 or parts[0] not in KINDS:
        return None
    try:
        seq = int(parts[1])
    except ValueError:
        return None
    return parts[0], seq, parts[2]


def new_state():
    return {"seq": 0, "last_rx": 0, "bad": 0}


def send(state, kind, value):
    state["seq"] += 1
    radio.send(encode(kind, state["seq"], value))   # send(str) adds b'\x01\x00\x01'
    print("tx", kind, state["seq"], value)


def receive(state):
    try:
        text = radio.receive()          # None when the queue is empty
    except ValueError:                  # bytes that are not a radio.send() string
        text = "?"
    if text is None:
        return None
    msg = decode(text)
    if msg is None:
        state["bad"] += 1
        print("rx bad", state["bad"])
        return None
    kind, seq, value = msg
    if seq <= state["last_rx"]:         # duplicate or old sequence number: ignore
        return None
    state["last_rx"] = seq
    print("rx", kind, seq, value)
    display.show(value if kind == "btn" else Image.YES, wait=False)
    return msg


def step(state):
    if button_a.was_pressed():
        send(state, "btn", "A")
    if button_b.was_pressed():
        send(state, "tmp", temperature())
    return receive(state)


def main():
    print("radio group", GROUP)
    state = new_state()
    while True:
        step(state)
        sleep(50)                       # poll often: the receive queue holds 3 messages


if __name__ == "__main__":
    main()

# Lab 08 - data logging: sample temperature and light once per interval,
# store each row with the V2 `log` module (MY_DATA on a real board) and
# print the same row as serial CSV (the export path in the simulator).
from microbit import *
try:
    import log                  # V2 only; on a V1 board -> serial CSV only
except ImportError:
    log = None

INTERVAL_MS = 1000
LABELS = ("temp", "light")      # column labels: set ONCE, before the first row


def setup():
    if log:
        # timestamp column "Time (seconds)" is added in front of the labels
        log.set_labels(*LABELS, timestamp=log.SECONDS)
    print("time_ms," + ",".join(LABELS))   # serial CSV header (our own format)


def sample():
    return {"temp": temperature(), "light": display.read_light_level()}


def to_csv(t_ms, row):
    # one CSV record: same column order as the header, numbers only, no quotes needed
    return ",".join([str(t_ms)] + [str(row[k]) for k in LABELS])


def new_state():
    return {"rows": 0, "logging": log is not None}


def step(state):
    row = sample()
    if state["logging"]:
        log.add(row)            # dict form; raises OSError(28) when the log is full
    print(to_csv(running_time(), row))
    state["rows"] += 1
    display.show(Image.SQUARE_SMALL if state["rows"] % 2 else Image.SQUARE, wait=False)
    return row


def main():
    setup()
    state = new_state()
    while True:
        step(state)
        sleep(INTERVAL_MS)      # sampling interval (run_every is the scheduled alternative)


if __name__ == "__main__":
    main()

# Lab 11 - a game as a state machine: "catch the dot".
# idle --A or shake--> play --6 s--> over --A--> idle; in play, press A when
# the moving dot is in the middle column to score.
from microbit import *

ROUND_MS = 6000            # one round, timed with running_time()
STEP_MS = 300              # the dot moves one column every 300 ms
TARGET_X = 2               # middle column

# transition table: (state, event) -> (next state, action). Anything else is ignored.
TRANSITIONS = {
    ("idle", "a"): ("play", "start"),
    ("idle", "shake"): ("play", "start"),
    ("play", "a"): ("play", "hit"),
    ("play", "shake"): ("idle", "abort"),
    ("play", "timeout"): ("over", "score"),
    ("over", "a"): ("idle", None),
}


def next_state(state, event):
    return TRANSITIONS.get((state, event), (state, None))


def new_game():
    return {"state": "idle", "score": 0, "started": 0}


def dot_x(game, now):
    return ((now - game["started"]) // STEP_MS) % 5


def events(game, now):
    # events come from buttons, gestures and time; the table decides what they mean
    found = []
    if button_a.was_pressed():
        found.append("a")
    if accelerometer.was_gesture("shake"):
        found.append("shake")
    if game["state"] == "play" and now - game["started"] >= ROUND_MS:
        found.append("timeout")    # time is an event too: elapsed ms since "start"
    return found


def handle(game, event, now):
    state, action = next_state(game["state"], event)
    if action == "start":
        game["score"], game["started"] = 0, now
    elif action == "hit":
        hit = dot_x(game, now) == TARGET_X
        game["score"] += 1 if hit else 0
        print("hit" if hit else "miss", game["score"])
    if state != game["state"]:
        print("{} -> {} ({})".format(game["state"], state, event))
        game["state"] = state
    if action == "score":
        print("score", game["score"])


def draw(game, now):
    if game["state"] == "play":
        display.clear()
        display.set_pixel(dot_x(game, now), 2, 9)
    elif game["state"] == "over":
        display.show(min(game["score"], 9), wait=False)
    else:
        display.show(Image.TARGET, wait=False)


def step(game):
    now = running_time()           # ms since start: never sleep() to measure time
    for event in events(game, now):
        handle(game, event, now)
    draw(game, now)


def main():
    print("game ready: A or shake to start")
    game = new_game()
    while True:
        step(game)
        sleep(20)


if __name__ == "__main__":
    main()
